use ethers::{
    abi::AbiEncode,
    providers::{Provider, Ws},
    types::{H160, U256},
};
use ethers_providers::Middleware;

pub async fn simulation(
    target_pool: H160,
    token_in: H160,
    token_out: H160,
    provider: Arc<Provider<Ws>>,
) -> Result<()> {
    let owner = create_new_wallet().1;
    let latest_block_number = provider.get_block_number().await?;
    let mut simulator = EvmSimulator::new(provider.clone(), Some(owner), latest_block_number);
    // create arboo contract
    println!("Create arboo...");
    let (_, bot_address) = create_new_wallet();
    simulator.deploy(bot_address, arboo_bytecode());

    // let eth_to_sell = U256::from(500) * U256::from(10).pow(U256::from(18));
    println!("Create wallet...");
    // set wallet balance
    let initial_eth_balance = U256::from(1000) * U256::from(10).pow(U256::from(18));
    let amount_in = U256::from(1_000_00) * U256::from(10).pow(U256::from(18));

    simulator.set_eth_balance(simulator.owner, initial_eth_balance);
    simulator.set_eth_balance(bot_address, initial_eth_balance);

    let tx_data = FlashSwapV2ToV3Call {
        pool_0: target_pool,
        fee_1: 0u32,
        token_in,
        token_out,
        amount_in,
    };
    let tx_data = tx_data.encode();
    let tx_data = bytes::Bytes::try_from(tx_data).unwrap();
    // create tx inputs
    let tx = Tx {
        caller: simulator.owner,
        transact_to: bot_address,
        data: tx_data,
        value: U256::from(0),
        gas_price: U256::zero(),
        gas_limit: 1_000_000u64,
    };

    simulator.call(tx).unwrap();

    let result = simulator.get_token_balance(token_in, simulator.owner);
    print!("Result:: {:?}", result);
    // send t
    //
    // check wallet balance
    //
    // report profit

    Ok(())
}
pub fn arboo_bytecode() -> Bytecode {
    let bytes = Bytecode::new_raw( "".bytes().collect());
    return bytes;
}
